style.css:
/* Beabadoobee Background Theme - Minimal Safe Version */

body {
  background: url("https://i.pinimg.com/736x/6c/69/e5/6c69e5f8be0ab275bcc10c56cb69853f.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
  color: #e9e9f0 !important;
  font-family: "Poppins", sans-serif !important;
}

body > * {
  background-color: rgba(0, 0, 0, 0.45) !important;
  backdrop-filter: blur(6px) !important;
}
